import clsx from 'clsx';
import { Fragment, useState } from 'react';
import { useFormContext } from 'react-hook-form';
import { useComCodeState } from '~/entities/comcode/lib/use-comcode-state';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { ComCodeParams } from '~/entities/comcode/model/types';
import { useEffectOnceAfterPageRendered } from '~/shared/lib/hooks';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';
import { TextInput } from '~/shared/ui/text-input/text-input';
import { BankSelectProps } from './base';

export const BankSelect = ({
  placeholder,
  register,
  name,
  option,
  classStr,
  isErrorPaddingPresent = true,
  isShowError,
}: BankSelectProps) => {
  const { comCode } = useComCodeState(COM_CODE.BANK);
  const [isOpenBottomSheet, setIsOpenBottomSheet] = useState(false);

  const handleCloseBottomSheet = () => {
    setIsOpenBottomSheet(false);
  };

  const { setValue, clearErrors, watch, getValues } = useFormContext();
  const defaultValue = getValues(name);
  const selectedValue = watch(name, defaultValue);
  const selectedLabel = comCode?.hash?.[selectedValue as keyof ComCodeParams]?.cdValueNm ?? '';

  const onInputClick = (event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    event.preventDefault();
    setIsOpenBottomSheet(true);
  };

  const onRadioChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setValue(name, event.target.value);
    setIsOpenBottomSheet(false);
    clearErrors(name);
  };

  useEffectOnceAfterPageRendered(() => {
    if (selectedValue?.length > 0) {
      setValue(name, selectedValue);
    }
  });

  return (
    <Fragment>
      <TextInput
        label={placeholder}
        {...register(name, option)}
        readOnly
        onClick={onInputClick}
        displayLabel={selectedLabel}
        selectMode
        labelClassStr={selectedValue ? `bank-logo  + ${selectedValue} ${classStr}` : classStr}
        isErrorPaddingPresent={isErrorPaddingPresent}
        isShowError={isShowError}
      />
      <BottomSheet title={placeholder} open={isOpenBottomSheet} onClose={handleCloseBottomSheet}>
        <div
          style={{ height: '100%', overflowY: 'auto' }}
          className="show-scrollbar mx-[24px] flex flex-row flex-wrap gap-[10px] pb-[30px] pt-[20px]"
        >
          {comCode?.tbSysCodeValueList?.map((item) => (
            <label
              htmlFor={item.cdValue!}
              key={item.cdValue}
              className={clsx(`bank-btm-sheet-btn text-[13px] ${item.cdValue}`, {
                'selected font-bold text-font-primary': selectedValue === item.cdValue,
              })}
            >
              <input
                className="hidden"
                type="radio"
                id={item.cdValue!}
                name={name}
                value={item.cdValue!}
                onChange={(event) => onRadioChange(event)}
              />
              {item.cdValueNm}
            </label>
          ))}
        </div>
      </BottomSheet>
    </Fragment>
  );
};
