import { useMutation } from '@tanstack/react-query';
import { FindRecipientRequestDTO, FindRecipientResponseDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useFindRecipientMutation = (
  options?: MutationOptions<FindRecipientRequestDTO, CBDCAxiosError, FindRecipientResponseDTO>,
) => {
  const mutation = useMutation<FindRecipientResponseDTO, CBDCAxiosError, FindRecipientRequestDTO>({
    ...options,
    mutationFn: exchangeApi.findRecipient,
  });

  return {
    ...mutation,
  };
};
