import { useEffect, useRef } from 'react';
import { useStore } from '~/app/store/store';
import { AllQRCode } from '~/entities/qr-code/model/types';
import { QRScanType } from '~/entities/qr-scan/model/types';

const isWalletAddressQRType = (type: QRScanType | undefined) => {
  return type === QRScanType.QR_지갑주소입력_수신자선택 || type === QRScanType.QR_지갑주소입력_수신자입력;
};

export const useQRScanListener = (callback?: (scannedQRCode: AllQRCode) => void) => {
  const qrScanType = useStore((state) => state.qrScannerSlice.options.qrScanType);
  const scannedQRCode = useStore((state) => state.qrScannerSlice.QRCode);
  const isValid = useStore((state) => state.qrScannerSlice.isValid());
  const callbackRef = useRef(callback);
  const lastProcessedRef = useRef<string | null>(null);

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  useEffect(() => {
    if (!isValid) {
      lastProcessedRef.current = null;
      return;
    }

    if (isWalletAddressQRType(qrScanType) || !!scannedQRCode.walletAddr) {
      const key = `${scannedQRCode.walletAddr ?? ''}:${scannedQRCode.bankCode ?? ''}:${scannedQRCode.txCode ?? ''}`;
      if (lastProcessedRef.current === key) {
        return;
      }
      lastProcessedRef.current = key;
      callbackRef.current?.({ ...scannedQRCode });
    }
  }, [isValid, scannedQRCode, qrScanType]);
};
