import { useState } from 'react';
import { useQRScan } from '~/entities/qr-scan/lib/use-qr-scan';
import { ScannerType } from '~/entities/qr-scan/model/types';
import qr_scan_loop from '~/shared/assets/img/qr_scan_loop.gif';
import i18n from '~/shared/i18n/i18n';
import { useEffectOnceAfterPageRendered } from '~/shared/lib/hooks';
import { useFixedButtonPosition } from '~/shared/lib/hooks/use-fixed-button-position';

export const WalletQRScanButton = () => {
  const [scanClassName, setScanClassName] = useState('');
  const buttonStyle = useFixedButtonPosition();
  const { openQRScanner } = useQRScan();

  const handleQrScan = () => {
    openQRScanner({
      scannerType: ScannerType.WalletQRScan,
    });
  };

  useEffectOnceAfterPageRendered(() => {
    setScanClassName('on');
  });

  return (
    <div className={`accnt-num-scan ${scanClassName}`} style={buttonStyle}>
      <button type="button" className="accnt-num-scan-btn" onClick={handleQrScan}>
        <div className="scan-icon" id="scan-icon">
          <img src={qr_scan_loop} />
        </div>
        <span>{i18n.t('scanWalletQRCode')}</span>
      </button>
    </div>
  );
};
