import { z } from 'zod';
import { FindRecipientResponseDTO } from '~/entities/exchange/api/dtos/types';
import { BaseExchangeContextSchema } from '~/entities/exchange/model/schemas';
import { FunnelStep } from './enums';

const 송금_Schema = BaseExchangeContextSchema.extend({
  // 수취인 정보 - 송금 시에만 필수
  aliasNm: z.string().optional(),
  walletInsttCd: z.string().optional(),
  personNm: z.string().optional(),
  shortBankName: z.string().optional(),
  // 수취인 데이터
  recipientData: z.custom<FindRecipientResponseDTO>().optional(),

  //발신인 지갑
  reqAliasNm: z.string().optional(),

  //거래유효확인
  txCd: z.string().optional(),
  draftCd: z.string().optional(),
}).partial();

export type 송금Context = z.infer<typeof 송금_Schema>;

export const 최근_수취인_선택_Schema = 송금_Schema.required({
  tokenId: true,
  trnscTypeCd: true,
  aliasNm: true,
  walletInsttCd: true,
});

export const 수취인_입력_Schema = 최근_수취인_선택_Schema.required({});

export const 금액입력_Schema = 수취인_입력_Schema.required({});

export const 금액확인_Schema = 금액입력_Schema.required({
  trnscAmt: true,
  personNm: true,
  shortBankName: true,
  draftCd: true,
});

export const 처리중_Schema = 금액확인_Schema;

export const 완료_Schema = 처리중_Schema.required({
  trnscId: true,
});

export type 최근_수취인_선택Context = z.infer<typeof 최근_수취인_선택_Schema>;
export type 수취인_입력Context = z.infer<typeof 수취인_입력_Schema>;
export type 금액입력Context = z.infer<typeof 금액입력_Schema>;
export type 금액확인Context = z.infer<typeof 금액확인_Schema>;
export type 처리중Context = z.infer<typeof 처리중_Schema>;
export type 완료Context = z.infer<typeof 완료_Schema>;

export type FunnelContextMap = {
  [FunnelStep.최근_수취인_선택]: 송금Context;
  [FunnelStep.수취인_입력]: 송금Context;
  [FunnelStep.금액입력]: 송금Context;
  [FunnelStep.금액확인]: 송금Context;
  [FunnelStep.처리중]: 송금Context;
  [FunnelStep.완료]: 송금Context;
};
